from typing import Any, AnyStr, Dict, Sequence, Tuple, Union

class SQLParams:
    in_style = None
    out_style = None

    def format(
        self,
        sql: AnyStr,
        params: Union[Dict[Union[str, int], Any], Sequence[Any]],
    ) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
        if self.in_style == 'named':
            if not isinstance(params, dict):
                raise ValueError("params must be a Mapping for named parameter style")
            out_params = {}
            formatted_sql = sql
            for key, value in params.items():
                out_key = self.out_style.format(key)
                out_params[out_key] = value
                formatted_sql = formatted_sql.replace(f":{key}", out_key)
            return formatted_sql, out_params
        elif self.in_style == 'ordinal':
            if not isinstance(params, Sequence):
                raise ValueError("params must be a Sequence for ordinal parameter style")
            out_params = []
            formatted_sql = sql
            for i, value in enumerate(params):
                out_key = self.out_style.format(i + 1)
                out_params.append(value)
                formatted_sql = formatted_sql.replace(f"${i + 1}", out_key)
            return formatted_sql, out_params
        else:
            raise ValueError("Unsupported parameter style")
