import datetime

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None

    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError("Invalid frequency format")

    try:
        number = int(parts[0])
    except ValueError:
        raise ValueError("Invalid number in frequency")

    unit = parts[1].lower()
    if unit == "seconds":
        return datetime.timedelta(seconds=number)
    elif unit == "minutes":
        return datetime.timedelta(minutes=number)
    elif unit == "hours":
        return datetime.timedelta(hours=number)
    elif unit == "days":
        return datetime.timedelta(days=number)
    elif unit == "weeks":
        return datetime.timedelta(weeks=number)
    elif unit == "months":
        # Approximate months as 30 days
        return datetime.timedelta(days=number * 30)
    elif unit == "years":
        # Approximate years as 365 days
        return datetime.timedelta(days=number * 365)
    else:
        raise ValueError("Invalid unit of time in frequency")
